{

"workflow": {
  "title": "Museum Loan Request Process",
  "summary": "A curator initiates a loan request for an object, with AI-assisted preparation and human oversight for approvals and risk management."
},
"evidence": [
  {"id": "ev-1", "quote": "A curator receives a loan request naming an object, destination and proposed dates."},
  {"id": "ev-2", "quote": "An AI assistant reads the request, the catalogue entry and the conservation report, then drafts a suitability summary and a proposed checklist."},
  {"id": "ev-3", "quote": "A conservator assesses the object's condition."},
  {"id": "ev-4", "quote": "The registrar checks availability, insurance and transport arrangements."},
  {"id": "ev-5", "quote": "The lending committee makes the final loan decision."},
  {"id": "ev-6", "quote": "If conservation evidence is missing, the case stays pending until the conservator responds."},
  {"id": "ev-7", "quote": "If the dates conflict with an existing exhibition, the registrar proposes alternatives."},
  {"id": "ev-8", "quote": "After approval, the registrar schedules the handover and records return-condition checks."},
  {"id": "ev-9", "quote": "A cancellation closes the request with a recorded reason."},
  {"id": "ev-10", "quote": "Access to precise storage locations is restricted to authorised museum staff."}
],
"facts": [
  {"id": "fact-1", "evidence_ids": ["ev-1", "ev-2", "ev-3", "ev-4", "ev-5"]},
  {"id": "fact-2", "evidence_ids": ["ev-6", "ev-7", "ev-8", "ev-9", "ev-10"]}
],
"assumptions": [
  {"id": "asm-1", "statement": "The AI assistant's output is considered reliable for preliminary assessments but requires human verification.", "rationale": "ev-2"}
],
"actors": [
  {"id": "actor-curator", "label": "Curator", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "actor-conservator", "label": "Conservator", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"id": "actor-registrar", "label": "Registrar", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-4", "ev-8"]},
  {"id": "actor-lending-committee", "label": "Lending Committee", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-5"]}
],
"data": [
  {"id": "data-loan-request", "label": "Loan Request", "description": "Object, destination, and proposed dates", "classification": "unknown", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "data-conservation-report", "label": "Conservation Report", "description": "Object condition and handling requirements", "classification": "unknown", "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "data-availability-check", "label": "Availability Check", "description": "Insurance and transport arrangements", "classification": "unknown", "source_state": "stated", "evidence_ids": ["ev-4"]}
],
"tools": [
  {"id": "tool-ai-assistant", "label": "AI Assistant", "purpose": "Draft suitability summaries and checklists", "mode": "unknown", "source_state": "stated", "evidence_ids": ["ev-2"]}
],
"steps": [
  {"id": "step-1", "label": "Receive Loan Request", "description": "Curator initiates request with object details", "actor_ids": ["actor-curator"], "input_data_ids": ["data-loan-request"], "output_data_ids": ["data-loan-request"], "tool_ids": ["tool-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "step-2", "label": "Draft Suitability Summary", "description": "AI assistant generates summary and checklist", "actor_ids": ["actor-ai-assistant"], "input_data_ids": ["data-loan-request", "data-conservation-report"], "output_data_ids": ["data-loan-request"], "tool_ids": ["tool-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "step-3", "label": "Assess Object Condition", "description": "Conservator evaluates conservation evidence", "actor_ids": ["actor-conservator"], "input_data_ids": ["data-conservation-report"], "output_data_ids": ["data-conservation-report"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"id": "step-4", "label": "Check Availability", "description": "Registrar verifies insurance and transport", "actor_ids": ["actor-registrar"], "input_data_ids": ["data-loan-request"], "output_data_ids": ["data-availability-check"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-4"]},
  {"id": "step-5", "label": "Lending Committee Decision", "description": "Final approval for loan", "actor_ids": ["actor-lending-committee"], "input_data_ids": ["data-loan-request", "data-conservation-report", "data-availability-check"], "output_data_ids": ["data-loan-request"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-5"]}
],
"decisions": [
  {"id": "decision-1", "step_id": "step-3", "question": "Is conservation evidence sufficient?", "criteria": ["ev-6"], "authority_actor_ids": ["actor-conservator"], "source_state": "stated", "evidence_ids": ["ev-6"]},
  {"id": "decision-2", "step_id": "step-4", "question": "Are dates conflicting with exhibitions?", "criteria": ["ev-7"], "authority_actor_ids": ["actor-registrar"], "source_state": "stated", "evidence_ids": ["ev-7"]}
],
"edges": [
  {"from_step_id": "step-1", "to_step_id": "step-2", "condition": "ev-1", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"from_step_id": "step-2", "to_step_id": "step-3", "condition": "ev-2", "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"from_step_id": "step-3", "to_step_id": "step-4", "condition": "ev-6", "source_state": "stated", "evidence_ids": ["ev-6"]},
  {"from_step_id": "step-4", "to_step_id": "step-5", "condition": "ev-7", "source_state": "stated", "evidence_ids": ["ev-7"]},
  {"from_step_id": "step-5", "to_step_id": "step-8", "condition": "ev-8", "source_state": "stated", "evidence_ids": ["ev-8"]},
  {"from_step_id": "step-5", "to_step_id": "step-9", "condition": "ev-9", "source_state": "stated", "evidence_ids": ["ev-9"]}
],
"requirements": [
  {"id": "req-1", "statement": "Loan requests must include object details, destination, and dates", "kind": "unknown", "source_state": "stated", "evidence_ids": ["ev-1"]}
],
"existing_controls": [
  {"id": "existing-1", "description": "AI assistant cannot approve loans or sign agreements", "step_ids": ["step-5"], "source_state": "stated", "evidence_ids": ["ev-2"]}
],
"risks": [
  {"id": "risk-1", "title": "Incomplete Conservation Evidence", "scenario": "Missing conservation data delays loan processing", "impact": "Operational delay", "step_ids": ["step-3"], "data_ids": ["data-conservation-report"], "evidence_ids": ["ev-6"], "uncertainty": "unknown", "proposed_priority": "high"},
  {"id": "risk-2", "title": "Date Conflict with Exhibition", "scenario": "Conflicting dates prevent loan approval", "impact": "Lost opportunity", "step_ids": ["step-4"], "data_ids": ["data-loan-request"], "evidence_ids": ["ev-7"], "uncertainty": "unknown", "proposed_priority": "medium"},
  {"id": "risk-3", "title": "Unauthorized Storage Access", "scenario": "Leak of storage locations compromises security", "impact": "Security breach", "step_ids": ["step-8"], "data_ids": ["data-loan-request"], "evidence_ids": ["ev-10"], "uncertainty": "unknown", "proposed_priority": "high"}
],
"controls": [
  {"id": "ctrl-1", "family": "data_quality", "recommendation": "Require conservation evidence before proceeding", "enforcement_point": "step-3", "risk_ids": ["risk-1"], "step_ids": ["step-3"], "owner_actor_ids": ["actor-conservator"], "validation": "Submit request without conservation evidence; expect denial or hold, verify no loan approval occurs, inspect decision evidence."},
  {"id": "ctrl-2", "family": "data_quality", "recommendation": "Validate date availability against exhibitions", "enforcement_point": "step-4", "risk_ids": ["risk-2"], "step_ids": ["step-4"], "owner_actor_ids": ["actor-registrar"], "validation": "Submit request with conflicting dates; expect alternative proposals, verify no loan approval occurs, inspect decision evidence."},
  {"id": "ctrl-3", "family": "data_quality", "recommendation": "Restrict storage location access to authorized staff", "enforcement_point": "step-8", "risk_ids": ["risk-3"], "step_ids": ["step-8"], "owner_actor_ids": ["actor-registrar"], "validation": "Attempt to access storage location without authorization; expect access denial, verify no loan documentation occurs, inspect access logs."},
  {"id": "ctrl-4", "family": "accountability_remediation", "recommendation": "Document all loan decisions with rationale", "enforcement_point": "step-5", "risk_ids": ["risk-1", "risk-2", "risk-3"], "step_ids": ["step-5"], "owner_actor_ids": ["actor-lending-committee"], "validation": "Review decision rationale for conflicting cases; expect clear justification, verify no loan approval occurs, inspect decision evidence."}
],
"gaps": [
  {"id": "gap-1", "description": "No catalogue API defined for object lookup", "related_ids": ["req-1"], "question_ids": ["question-1"], "blocking": true},
  {"id": "gap-2", "description": "Retention periods for loan records not specified", "related_ids": ["req-1"], "question_ids": ["question-2"], "blocking": true}
],
"questions": [
  {"id": "question-1", "question": "Who will define the catalogue API for object lookup?", "related_ids": ["gap-1"],"blocking": true},
  {"id": "question-2", "question": "What retention periods apply to loan records?", "related_ids": ["gap-2"], "blocking": true}
],
"human_authority": {
  "accountable_actor_ids": ["actor-curator", "actor-conservator", "actor-registrar", "actor-lending-committee"],
  "reviewer_actor_ids": ["actor-lending-committee"],
  "approval_points": [
    {"step_id": "step-5", "recommended_actor_ids": ["actor-lending-committee"], "reason": "Final loan decision requires committee approval", "control_ids": ["ctrl-4"]}
  ],
  "escalation": "If a loan request is denied, the curator must escalate to the lending committee for review."
}
}
